package com.keepcalm.placementportal;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest@AutoConfigureMockMvc class OpenApiContractTest{@Autowired MockMvc mvc;@Test void publishesCanonicalOpenApiPaths()throws Exception{mvc.perform(get("/v3/api-docs")).andExpect(status().isOk()).andExpect(jsonPath("$.info.version").value("v1")).andExpect(jsonPath("$.paths['/api/v1/auth/login']").exists()).andExpect(jsonPath("$.paths['/api/v1/students/me/profile']").exists()).andExpect(jsonPath("$.paths['/api/v1/admin/drives/{driveId}/publish']").exists()).andExpect(jsonPath("$.paths['/api/v1/admin/offers']").exists());}}
